package com.ecole.gestion_scolaire.finance.entity;
import jakarta.persistence.*;
import java.time.*;
import java.math.BigDecimal;
@Entity @Table(name="tariff") public class Tariff { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="school_year_id",nullable=false) private Long schoolYearId; @Column(name="fee_type_id",nullable=false) private Long feeTypeId; @Column(name="level_id") private Long levelId; @Column(name="class_group_id") private Long classGroupId; @Column(name="campus_id") private Long campusId; @Column(nullable=false,precision=14,scale=2) private BigDecimal amount; @Column(name="billing_frequency",nullable=false,length=30) private String billingFrequency; @Column(name="valid_from",nullable=false) private LocalDate validFrom; @Column(name="valid_until") private LocalDate validUntil; @Column(nullable=false) private boolean active; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; @PrePersist void pre(){var n=OffsetDateTime.now();if(createdAt==null)createdAt=n;updatedAt=n;} @PreUpdate void upd(){updatedAt=OffsetDateTime.now();} public Long getId(){return id;} public Long getSchoolYearId(){return schoolYearId;} public void setSchoolYearId(Long v){schoolYearId=v;} public Long getFeeTypeId(){return feeTypeId;} public void setFeeTypeId(Long v){feeTypeId=v;} public Long getLevelId(){return levelId;} public void setLevelId(Long v){levelId=v;} public Long getClassGroupId(){return classGroupId;} public void setClassGroupId(Long v){classGroupId=v;} public Long getCampusId(){return campusId;} public void setCampusId(Long v){campusId=v;} public BigDecimal getAmount(){return amount;} public void setAmount(BigDecimal v){amount=v;} public String getBillingFrequency(){return billingFrequency;} public void setBillingFrequency(String v){billingFrequency=v;} public LocalDate getValidFrom(){return validFrom;} public void setValidFrom(LocalDate v){validFrom=v;} public LocalDate getValidUntil(){return validUntil;} public void setValidUntil(LocalDate v){validUntil=v;} public boolean isActive(){return active;} public void setActive(boolean v){active=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;} }
